import { connection } from 'next/server'

export async function CurrentTimestamp() {
  // Stops prerendering: everything below runs only once a real request arrives,
  // so `new Date()` is evaluated per request instead of being baked in at build.
  await connection()

  const now = new Date()

  return (
    <p>
      Server time: <time dateTime={now.toISOString()}>{now.toISOString()}</time>
    </p>
  )
}

